    "points": 1,
    "title": "Logistic Population Growth and Environmental Resistance",
    "content": "<p>In the Verhulst-Pearl logistic growth equation ($\\frac{dN}{dt} = rN\\left(1 - \\frac{N}{K}\\right)$), what does the parameter $K$ represent?</p>",
