    "modelSolution": "1) Copper payable: $0.24\\text{ t} \\times (8000 - 220) = \\$1,867.20$.\n2) Gold payable: $7.2\\text{ g} \\times 59.84 = \\$430.85$.\n3) Total NSR: $1867.20 + 430.85 - 80.00 = \\$2,218.05/\\text{t}$."
