    "modelSolution": "1) Per hectare: $2.4 \\times (1 - 0.85) = 0.36\\text{ t C}/(\\text{ha}\\cdot\\text{yr})$.\n2) Total mire: $5,000\\text{ ha} \\times 0.36 = 1,800\\text{ t C/yr}$."
