    "modelSolution": "1) Generated $SO_2$: $500\\text{ t} \\times 0.02 \\times 0.95 \\times (64.06 / 32.06) = 18.98\\text{ t/h}$.\n2) Stack emission: $18.98\\text{ t/h} \\times (1 - 0.92) = 1.519\\text{ t/h} = 421.8\\text{ g/s}$."
